SELECT item_id,payload,payload_bytes,live,settlement_charge_bytes AS settlement_bytes,CAST(json_object('id',item_id,'digest',digest,'sender',json(sender),'acceptanceBound',acceptance_bound,'settlementBytes',settlement_bytes,'progress',json_object('kind',progress,'value',json_object('attempt',attempt,'outcome',json(CASE outcome_kind WHEN 'delivered' THEN json_object('kind',outcome_kind,'value',json_object('acceptance',json(outcome_acceptance))) WHEN 'refused' THEN json_object('kind',outcome_kind,'value',json_object('reason',json(CASE WHEN refusal_kind IN ('processingFailed','recipientRefused') THEN json_object('kind',refusal_kind,'value',json(CASE refusal_kind WHEN 'processingFailed' THEN json_object('kind',refusal_failure) WHEN 'recipientRefused' THEN json_object('code',refusal_code) ELSE 'null' END)) ELSE json_object('kind',refusal_kind) END))) WHEN 'prevented' THEN json_object('kind',outcome_kind,'value',json_object('cancel',outcome_cancel_item_id)) ELSE json_object('kind',outcome_kind) END))),'reportSeq',report_seq,'releaseRequested',json(CASE release_requested WHEN 0 THEN 'false' WHEN 1 THEN 'true' ELSE 'null' END)) AS TEXT) AS record FROM _fleet_sync_inbox_items WHERE item_id=?1;
